import{_ as r,l as i,o as t,c as l,v as a,p as s,x as e,d as c,i as d,S as u}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"COCONUT 潜空间思维链","description":"","frontmatter":{"title":"COCONUT 潜空间思维链","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/coconut-latent-cot.md","filePath":"llm/coconut-latent-cot.md","lastUpdated":1789023840000}'),h={name:"llm/coconut-latent-cot.md"};function p(C,o,T,m,k,_){const n=i("Mermaid");return t(),l("div",null,[o[1]||(o[1]=a('<h1 id="coconut-潜空间思维链" tabindex="-1">COCONUT 潜空间思维链 <a class="header-anchor" href="#coconut-潜空间思维链" aria-label="Permalink to &quot;COCONUT 潜空间思维链&quot;">​</a></h1><div class="epigraph"><p>多数词只为通顺，少数关键 token 却要做规划；与其把推理锁在词表里，不如把最后隐状态直接喂回下一输入嵌入。</p><footer>—— Hao, Sukhbaatar, Su, Li, Hu, Weston, Tian，Training Large Language Models to Reason in a Continuous Latent Space，arXiv:2412.06769</footer></div><p>思维链把中间步骤写成自然语言，等于把 Transformer 的有效深度随生成变长，但也强迫每步选一个词。Hao 等人（FAIR at Meta / UCSD）提出 <strong>Coconut</strong>（Chain of Continuous Thought）：语言模式照常预测 token；潜模式把最后隐状态当作「连续思维」，不经 lm_head 与 embedding，直接当下一步输入。特殊 token <code>&lt;bot&gt;</code> / <code>&lt;eot&gt;</code> 标记潜段。训练用多阶段课程：先普通 CoT，第 \\(k\\) 阶段把前 \\(k\\) 个语言步骤换成 \\(k\\times c\\) 个连续思维，损失只打在剩余文本上。主实验骨干是 GPT-2。代码：github.com/facebookresearch/coconut。本篇写潜模式与 BFS 式搜索，不把「隐空间推理」写成已替代 o1 级长思维。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Next-token 训练把推理机锁在词表里。CoT 有效，但大部分 token 只维持流畅，关键抉择却与流畅 token 分到几乎相同的计算预算。压缩 CoT 或在关键 token 前插入填充符，仍在语言空间里打转。神经影像表明人脑语言网络在许多推理任务中并不活跃；Fedorenko 等论证语言首先是交际工具。Coconut 的问题是：若允许无语言约束的连续状态，再只在必要时译回词，规划型任务会不会少幻觉、少过早承诺。</p><p>语言 CoT 是贪心深度优先：第一步选错，后面要么编造不存在的边，要么走到错误目标。需要回溯的逻辑题会惩罚这种承诺。先前工作用显式树搜索或把搜索轨迹拿来训练；Coconut 问的是，连续表示能否<strong>不经显式搜索算法</strong>就维持多条候选。</p><h3 id="课程来自-icot-目标却不同" tabindex="-1">课程来自 iCoT，目标却不同 <a class="header-anchor" href="#课程来自-icot-目标却不同" aria-label="Permalink to &quot;课程来自 iCoT，目标却不同&quot;">​</a></h3><p>Deng 等 iCoT 逐步删掉思维链开头的 token，直到只剩答案，把推理「内化」。Coconut 同样分阶段，但删掉的语言步骤换成连续思维，目标不是压缩进权重，而是让连续状态去<strong>预测未来推理</strong>。损失不鼓励把被删步骤原样压进隐向量，因此表示可以与人类语言不同。无课程的 Coconut（直接最后一阶段）在实验里不比 No-CoT 好：潜空间不会从问答对里自动长出来。</p><p><span class="marginnote">插入 <code>&lt;bot&gt;</code> 紧跟问题；<code>&lt;eot&gt;</code> 实验里用固定潜长度，二分类早停也可用，两者差不多。潜步上 \\(\\mathrm{softmax}(Wh_t)\\) 仍可算，仅供探测，不定义潜思维的词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准 LM：\\(H_t=\\mathrm{Transformer}(E_t)\\)，\\(p(x_{t+1}|x_{\\le t})=\\mathrm{softmax}(W h_t)\\)。潜模式在 \\(i\\lt t\\lt j\\) 时 \\(E_t\\) 含 \\(h_i,\\ldots,h_{t-1}\\) 而非 \\(e(x)\\)。最后隐状态已经过最终 Norm，幅度可控，可反传。\\(n\\) 个潜思维需要 \\(n+1\\) 次前向（可用 KV 缓存），串行前向是训练效率的已知瓶颈。</p><p>数据集。数学：GSM8k，用 Deng 等合成链，\\(c=2\\)，约 3 个替换阶段后再加一阶段去掉剩余语言链。逻辑：ProntoQA；以及新提出的 <strong>ProsQA</strong>（带搜索的证明问答）——概念关系是 DAG，自然语言陈述，要找有效路径，比 ProntoQA 更多干扰分支。ProsQA 最多 6 步，故 \\(N=6\\) 阶段。推理时把潜步数与最后训练阶段对齐，贪心解码。</p><p>表 1（准确率 / 生成 token）：GSM8k 上 Coconut 34.1% / 8.2 token，CoT 42.9 / 25.0，No-CoT 16.5 / 2.2，iCoT 30.0 / 2.2。ProntoQA：Coconut 99.8 / 9.0，CoT 98.8 / 92.5。ProsQA：Coconut 97.0 / 14.2，CoT 77.5 / 49.4。无课程变体 GSM8k 仅 14.4。Pause token 与「无思维的课程」在 GSM8k 上明显弱于连续思维。增加 \\(c\\) 从 0→1→2，GSM8k 上升，说明连续思维可以链式加计算。</p>',13)),(t(),s(u,null,{default:e(()=>[d(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%20token%22%5D%20--%3E%20BOT%5B%22%EF%BC%9Cbot%3E%22%5D%0A%20%20BOT%20--%3E%20H1%5B%22%E8%BF%9E%E7%BB%AD%E6%80%9D%E7%BB%B4%20h%22%5D%0A%20%20H1%20--%3E%20H2%5B%22%E5%86%8D%E5%96%82%E5%9B%9E%E4%B8%BA%E5%B5%8C%E5%85%A5%22%5D%0A%20%20H2%20--%3E%20EOT%5B%22%EF%BC%9Ceot%3E%22%5D%0A%20%20EOT%20--%3E%20ANS%5B%22%E8%AF%AD%E8%A8%80%EF%BC%9A%E5%89%A9%E4%BD%99%E9%93%BE%E6%88%96%E7%AD%94%E6%A1%88%22%5D%0A"})]),fallback:e(()=>[...o[0]||(o[0]=[c(" Loading... ",-1)])]),_:1})),o[2]||(o[2]=a('<h3 id="prosqa-上的路径分类" tabindex="-1">ProsQA 上的路径分类 <a class="header-anchor" href="#prosqa-上的路径分类" aria-label="Permalink to &quot;ProsQA 上的路径分类&quot;">​</a></h3><p>对完整语言链：正确最短路、更长合法路、幻觉边、错误目标。对只输出部分语言的 Coconut，用「存在合法补全」来归类。\\(k\\) 从 0 加到 6，答案准确率上升，幻觉与错误目标下降。语言 CoT 常在死胡同后编造边；潜推理推迟承诺。探测显示第一步连续思维对多个子节点保持质量（隐式价值函数），第二步再收窄——像 BFS 而不是贪心 DFS。节点高度（到叶的距离）越大，价值估计越糊：这解释了为何晚决策更好。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连续向量可以叠加多条下一跳，词表采样必须塌缩成一个 token。这不是训练时显式教了搜索，而是课程 + 连续残差把「尚未决定」表示成叠加。数学题上，把第一个连续思维解码到词，常对应中间变量，说明状态里有计算图节点，而不只是流畅短语。GSM8k 上 Coconut 未超过完整 CoT，但在准确率–token 曲线上优于逐步删语言步的 CoT：少说话时掉点更慢。</p><p>与 <a href="/llm/rmt">RMT</a> 的差别：RMT 的记忆 token 跨段传递压缩历史；Coconut 的连续思维是逐步推理状态，服务的是规划，不是长文档缓存。与暂停 token 的差别：暂停仍是离散、无内容的槽；连续思维携带上一层全部 \\(d\\) 维信息。</p><p><span class="marginnote">骨干是 GPT-2，GSM8k 34% 不是旗舰数学模型数字。引用「超过 CoT」必须限定在 ProntoQA / ProsQA 这类强规划任务。无课程失败说明潜推理目前依赖语言链作为脚手架。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="可解释性与并行" tabindex="-1">可解释性与并行 <a class="header-anchor" href="#可解释性与并行" aria-label="Permalink to &quot;可解释性与并行&quot;">​</a></h3><p>潜段不可读，探测用强迫解码，不是忠实思维链。产品若需要可审计推理，仍要在 <code>&lt;eot&gt;</code> 后强制语言。训练的多步前向阻碍大规模预训；论文把扩到预训列为未来。固定潜长度浪费简单题、不够难的题。强化学习长思维（R1 一类）仍在语言空间买计算；Coconut 证明另一条轴，不是替换。探测用的价值函数是强迫解码后的概念概率，不是训练目标里的显式搜索标签；因此「涌现 BFS」是行为描述，不要写成已实现可证明的树搜索算法。</p><p>出处：Hao et al.，arXiv:2412.06769，FAIR at Meta。iCoT：Deng et al. 2405.14838。ProsQA 为本文构造。后续理论工作讨论连续 CoT 的叠加态效率，引用时标明不是 2412 原文实验。</p><p><span class="marginnote">出处：Hao, Sukhbaatar, Su, Li, Hu, Weston, Tian，<em>Training Large Language Models to Reason in a Continuous Latent Space</em>，arXiv:2412.06769。代码 facebookresearch/coconut。CoT 经典出处 Wei et al. 2022。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Coconut 把最后隐状态循环为下一嵌入，在潜空间链式推理。</li><li>多阶段课程用语言 CoT 当脚手架；无课程则失败。</li><li>连续思维可编码多条下一跳，行为接近 BFS，利于 ProsQA 类规划。</li><li>GSM8k 提升相对 No-CoT，仍低于完整语言 CoT；逻辑任务上更准且更短。</li><li>出处：Hao et al.，arXiv:2412.06769。</li></ul>',13))])}const g=r(h,[["render",p]]);export{A as __pageData,g as default};
